435	fn rsplit_delimiter<'s, 'o>(
436	    value: Result<&'s str, &'o OsStr>,
437	    delimiter: Option<char>,
438	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
439	    let delimiter = delimiter?;
440	    let value = value.ok()?;
441	    let pos = value.rfind(delimiter)?;
442	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
443	    Some((Some(prefix), Ok(value)))
444	}
