446	fn complete_value_candidates(
447	    value: &OsStr,
448	    completer: &dyn ValueCandidates,
449	) -> Vec<CompletionCandidate> {
450	    debug!("complete_value_candidates: value={value:?}");
451	
452	    let mut values = completer.candidates();
453	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
454	    values
455	}
