535	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
536	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
537	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
538	    debug!("shorts: name={}", p.get_name());
539	
540	    p.get_arguments()
541	        .filter_map(|a| {
542	            a.get_short_and_visible_aliases().map(|shorts| {
543	                shorts.into_iter().map(|s| {
544	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
545	                        a.get_help()
546	                            .cloned()
547	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
548	                    )
549	                })
550	            })
551	        })
552	        .flatten()
553	        .collect()
554	}
555	
556	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
557	    candidate
558	        .help(arg.get_help().cloned())
559	        .id(Some(format!("arg::{}", arg.get_id())))
560	        .tag(Some(
561	            arg.get_help_heading()
562	                .unwrap_or("Options")
563	                .to_owned()
564	                .into(),
565	        ))
566	        .display_order(Some(arg.get_display_order()))
567	        .hide(arg.is_hide_set())
568	}
