601	fn populate_command_candidate(
602	    candidate: CompletionCandidate,
603	    cmd: &clap::Command,
604	    subcommand: &clap::Command,
605	) -> CompletionCandidate {
606	    candidate
607	        .help(subcommand.get_about().cloned())
608	        .id(Some(format!("command::{}", subcommand.get_name())))
609	        .tag(Some(
610	            cmd.get_subcommand_help_heading()
611	                .unwrap_or("Commands")
612	                .to_owned()
613	                .into(),
614	        ))
615	        .display_order(Some(subcommand.get_display_order()))
616	        .hide(subcommand.is_hide_set())
617	}
618	
619	/// Parse the short flags and find the first `takes_values` option.
620	///
621	/// Returns the raw leading flags, every matched argument, the first
622	/// `takes_values` option (if any), and the remaining unparsed flags.
623	fn parse_shortflags<'c, 's>(
624	    cmd: &'c clap::Command,
625	    mut short: clap_lex::ShortFlags<'s>,
626	) -> (
627	    String,
628	    Vec<&'c clap::Arg>,
629	    Option<&'c clap::Arg>,
630	    clap_lex::ShortFlags<'s>,
631	) {
632	    let takes_value_opt;
633	    let mut matched_opts = Vec::new();
634	    let mut leading_flags = String::new();
635	    // Find the first takes_values option.
636	    loop {
637	        match short.next_flag() {
638	            Some(Ok(opt)) => {
639	                leading_flags.push(opt);
640	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
641	                if let Some(opt) = opt {
642	                    matched_opts.push(opt);
643	                }
644	                if opt
645	                    .map(|o| o.get_num_args().expect("built").takes_values())
646	                    .unwrap_or(false)
647	                {
648	                    takes_value_opt = opt;
649	                    break;
650	                }
651	            }
652	            Some(Err(_)) | None => {
653	                takes_value_opt = None;
654	                break;
655	            }
656	        }
657	    }
658	
659	    (leading_flags, matched_opts, takes_value_opt, short)
660	}
661	
662	/// Whether the argument can be addressed by the long flag `flag`,
663	/// including visible and hidden aliases.
664	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
665	    arg.get_long() == Some(flag)
666	        || arg
667	            .get_all_aliases()
668	            .is_some_and(|aliases| aliases.contains(&flag))
669	}
670	
671	/// Whether the argument can be addressed by the short flag `flag`,
672	/// including visible and hidden aliases.
673	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
674	    arg.get_short() == Some(flag)
675	        || arg
676	            .get_all_short_aliases()
677	            .is_some_and(|aliases| aliases.contains(&flag))
678	}
679	
680	/// Remove candidates for arguments that conflict with arguments already
681	/// present on the command line.
682	///
683	/// Conflicts only need to be declared on one of the two arguments; a
684	/// candidate is removed when either it or an already-used argument names
685	/// the other as a conflict. Anything that is not an argument candidate
686	/// (positional values, subcommands, custom candidates) is left untouched.
687	fn filter_conflicting_candidates(
688	    completions: &mut Vec<CompletionCandidate>,
689	    cmd: &clap::Command,
690	    used_args: &[clap::Id],
691	) {
692	    if used_args.is_empty() {
693	        return;
694	    }
695	    completions.retain(|candidate| {
696	        let Some(arg) = candidate
697	            .get_id()
698	            .and_then(|id| id.strip_prefix("arg::"))
699	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
700	        else {
701	            return true;
702	        };
703	        !used_args.iter().any(|used_id| {
704	            cmd.get_arguments()
705	                .find(|a| a.get_id() == used_id)
706	                .is_some_and(|used| args_conflict(cmd, arg, used))
707	        })
708	    });
709	}
710	
711	/// Whether `first` and `second` conflict, no matter which one declares it.
712	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
713	    cmd.get_arg_conflicts_with(first)
714	        .iter()
715	        .any(|c| c.get_id() == second.get_id())
716	        || cmd
717	            .get_arg_conflicts_with(second)
718	            .iter()
719	            .any(|c| c.get_id() == first.get_id())
720	}
721	
722	/// Parse the positional arguments. Return the new state and the new positional index.
723	fn parse_positional<'a>(
724	    cmd: &clap::Command,
725	    pos_index: usize,
726	    is_escaped: bool,
727	    state: ParseState<'a>,
728	) -> (ParseState<'a>, usize) {
729	    let pos_arg = cmd
730	        .get_positionals()
731	        .find(|p| p.get_index() == Some(pos_index));
732	    let num_args = pos_arg
733	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
734	        .unwrap_or(1);
735	
736	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
737	        if num_args > 1 {
738	            (ParseState::Pos((pos_index, 1)), pos_index)
739	        } else {
740	            if is_escaped {
741	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
742	            } else {
743	                (ParseState::ValueDone, pos_index + 1)
744	            }
745	        }
746	    };
747	    match state {
748	        ParseState::ValueDone => {
749	            update_state_with_new_positional(pos_index)
750	        },
751	        ParseState::Pos((prev_pos_index, num_arg)) => {
752	            if prev_pos_index == pos_index {
753	                if num_arg + 1 < num_args {
754	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
755	                } else {
756	                    if is_escaped {
757	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
758	                    } else {
759	                        (ParseState::ValueDone, pos_index + 1)
760	                    }
761	                }
762	            } else {
763	                update_state_with_new_positional(pos_index)
764	            }
765	        }
766	        ParseState::Opt(..) => unreachable!(
767	            "This branch won't be hit,
768	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
769	        ),
770	    }
771	}
772	
773	/// Parse optional flag argument. Return new state
774	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
775	    let range = opt.get_num_args().expect("built");
776	    let max = range.max_values();
777	    if count < max {
778	        ParseState::Opt((opt, count + 1))
779	    } else {
780	        ParseState::ValueDone
781	    }
782	}
783	
784	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
785	    cmd.get_positionals()
786	        .find(|a| a.get_index() == Some(pos_index))
787	        .map(|p| p.is_allow_hyphen_values_set())
788	        .unwrap_or(false)
789	}
790	
791	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
792	    let val = arg.to_value_os();
793	    if val.starts_with("-") {
794	        if let ParseState::Opt((opt, _)) = state {
795	            return opt.is_allow_hyphen_values_set();
796	        }
797	    }
798	
799	    false
800	}
